// AEAD is an authenticated-encryption-with-associated-data scheme. Each
// implementation owns its complete self-describing wire framing
// ([Version][id][nonce][ciphertext||tag]) so the registry can dispatch Open by
// reading the 1-byte id, and so the nonce — generated from crypto/rand inside
// Seal — never reaches a caller. Implementations MUST be safe for concurrent
// use and MUST return the shared non-oracle DecryptionFailed for every Open
// failure (bad tag, bad header, wrong key) so they cannot become an oracle.
//
// IFACE-PLUGIN: the registry hands plug-in AEAD instances back to callers behind
// this interface; concrete scheme types stay unexported in their own packages.
type AEAD interface {
	// Algorithm reports the canonical key under which this scheme registers.
	Algorithm() Algorithm
	// ID reports the 1-byte wire identifier embedded in the box header so Open
	// can resolve the scheme without the caller naming it.
	ID() byte
	// Seal encrypts plaintext, binding aad, and returns the self-framed box
	// (Version + id + random nonce + ciphertext||tag).
	Seal(key Key, plaintext, aad []byte) (box []byte, err error)
	// Open reverses Seal: it validates the framing, decrypts, and verifies aad,
	// returning the plaintext or the non-oracle DecryptionFailed.
	Open(key Key, box, aad []byte) (plaintext []byte, err error)
}

// Agreement is a key-agreement scheme (Diffie-Hellman style): it produces an
// ephemeral keypair and derives a shared secret from a local private key and a
// peer public key. The raw Shared output is low-level key material and MUST be
// run through a KDF (a Deriver) before use as a key — the pkg/v1 facade never
// hands the raw secret back to generic callers. Implementations self-register
// via RegisterAgreement.
//
// IFACE-PLUGIN: the registry hands plug-in Agreement instances back behind this
// interface; concrete scheme types stay unexported in their own packages.
type Agreement interface {
	// Algorithm reports the canonical key under which this scheme registers.
	Algorithm() Algorithm
	// GenerateKey draws a fresh public/private keypair from the scheme's
	// entropy source.
	GenerateKey() (pub, priv []byte, err error)
	// Shared derives the raw shared secret from priv and peerPub. The result
	// MUST be passed through a KDF before any use as a key.
	Shared(priv, peerPub []byte) (secret []byte, err error)
}

// Deriver is a key-derivation function for KEY SEPARATION: it expands one
// high-entropy secret into independent, purpose-bound subkeys. It is NOT a
// password hash — the input must already be a strong key (an AEAD Key, an HKDF
// PRK, a Diffie-Hellman shared secret), never a human password. Password
// stretching (argon2id) is a separate, deliberately slow port.
//
// salt is optional domain randomness (nil is allowed); info is a context label
// that binds each subkey to its purpose ("aead-key", "mac-key", …) so two
// derivations from the same secret never collide. Implementations MUST be safe
// for concurrent use.
//
// IFACE-PLUGIN: the registry hands plug-in Deriver instances back to callers
// behind this interface; concrete scheme types stay unexported in their own
// packages.
type Deriver interface {
	// Algorithm reports the canonical key under which this scheme registers.
	Algorithm() Algorithm
	// Derive expands secret (with optional salt and the context label info) into
	// a length-byte subkey, or DerivationFailed when length exceeds the scheme's
	// maximum output.
	Derive(secret, salt []byte, info string, length int) (subkey []byte, err error)
}

// Hasher is a fingerprint / content-addressing hash scheme producing a
// non-keyed digest of arbitrary bytes (content IDs, cache keys, dedup keys).
//
// It is explicitly NOT authentication: no Hasher is a MAC, none takes a key,
// and a digest is public — never branch on a secret-dependent comparison of
// one. Keyed/authenticated integrity belongs to the AEAD and (future) signature
// ports. Implementations self-register via RegisterHasher.
//
// IFACE-PLUGIN: the registry hands plug-in Hasher instances back behind this
// interface; concrete scheme types stay unexported in their own packages.
type Hasher interface {
	// Algorithm reports the canonical key under which this hasher registers.
	Algorithm() Algorithm
	// New returns a fresh hash.Hash for streaming (io.Copy) or one-shot use.
	New() hash.Hash
}

// MAC is a detached message-authentication-code scheme: it binds a secret Key
// to a message and yields an authentication tag. Unlike a Hasher digest, a MAC
// tag IS secret-comparison-sensitive — callers MUST route equality through
// Verify (constant-time), never `==` or bytes.Equal, which is the exact inverse
// of the Hasher rule. Implementations self-register via RegisterMAC.
//
// IFACE-PLUGIN: the registry hands plug-in MAC instances back behind this
// interface; concrete scheme types stay unexported in their own packages.
type MAC interface {
	// Algorithm reports the canonical key under which this MAC registers.
	Algorithm() Algorithm
	// Tag returns the authentication tag over message under key.
	Tag(key Key, message []byte) []byte
	// Verify reports whether tag authenticates message under key, using a
	// constant-time comparison so it never becomes a timing oracle.
	Verify(key Key, message, tag []byte) bool
	// New returns a fresh streaming hash.Hash keyed by key, paralleling
	// Hasher.New, for incremental tagging over large inputs.
	New(key Key) hash.Hash
}

// PasswordHasher stretches a human password into a slow, salted, self-describing
// PHC-string hash for storage. UNLIKE the Deriver (key separation) and Hasher
// (fingerprints) ports, this one is DELIBERATELY SLOW and salted: it is the only
// crypto surface meant to consume a low-entropy human secret.
//
// The returned hash is a PHC string (`$id$params$salt$digest`) that embeds the
// scheme id and its cost parameters, so Verify needs no side-channel: the stored
// string fully describes how to check it. Implementations MUST compare digests
// in constant time and MUST be safe for concurrent use.
//
// IFACE-PLUGIN: the registry hands plug-in PasswordHasher instances back to
// callers behind this interface; concrete scheme types stay unexported.
type PasswordHasher interface {
	// Algorithm reports the canonical key under which this scheme registers; it
	// is also the PHC id segment (the first `$`-delimited field).
	Algorithm() Algorithm
	// Hash returns a PHC-string hash of password with a fresh random salt and
	// the scheme's current cost parameters, or PasswordHashFailed on an entropy
	// fault.
	Hash(password []byte) (phc string, err error)
	// Verify reports whether password matches the stored PHC hash, comparing in
	// constant time. A malformed phc returns InvalidPasswordHash; a genuine
	// mismatch is (false, nil) so Verify is not an oracle on WHY it failed.
	Verify(password []byte, phc string) (ok bool, err error)
	// NeedsRehash reports whether phc was produced with cost parameters weaker
	// than this scheme's current policy, so callers can transparently re-hash on
	// a successful login. A malformed phc reports false (Verify surfaces the error).
	NeedsRehash(phc string) (stale bool)
}

// Signer is a detached digital-signature scheme over a public/private keypair.
// Keys and signatures are scheme-specific byte slices (their lengths are fixed
// per scheme); the registry dispatches on the Algorithm name. Implementations
// MUST be safe for concurrent use, MUST NOT panic on a malformed key (return
// SigningFailed instead), and Verify MUST run in constant time with respect to
// the signature so it cannot become a timing oracle.
//
// Unlike the AEAD port, a signature scheme has no hidden nonce and no wire
// framing: the caller holds the keypair and chooses what bytes to sign. The
// private key is secret material — treat it like Key.Bytes(): never log it.
//
// IFACE-PLUGIN: the registry hands plug-in Signer instances back to callers
// behind this interface; concrete scheme types stay unexported in their own
// packages.
type Signer interface {
	// Algorithm reports the canonical key under which this scheme registers.
	Algorithm() Algorithm
	// GenerateKey draws a fresh keypair from crypto/rand, returning the public
	// and private key bytes (or KeyGenerationFailed on a host entropy fault).
	GenerateKey() (pub, priv []byte, err error)
	// Sign produces a detached signature over message using priv, or
	// SigningFailed when priv is not a well-formed private key for this scheme.
	Sign(priv, message []byte) (sig []byte, err error)
	// Verify reports whether sig is a valid signature for message under pub. A
	// malformed key or signature is reported as false, never as a panic.
	Verify(pub, message, sig []byte) (ok bool)
}

// StreamSealer is a streaming authenticated-encryption scheme: it seals and
// opens an io.Writer / io.Reader pair in fixed-size chunks under a Key and
// associated data, extending the whole-buffer AEAD domain to arbitrarily large
// payloads. The Reader honours the hold-back contract: it MUST NOT surface a
// chunk's plaintext downstream before that chunk authenticates, and a stream cut
// short surfaces as StreamTruncated rather than as accepted plaintext (the
// final chunk carries a flag that a truncated stream never reaches).
// Implementations self-register via RegisterStreamSealer.
//
// IFACE-PLUGIN: the registry hands plug-in StreamSealer instances back behind
// this interface; concrete scheme types stay unexported in their own packages.
type StreamSealer interface {
	// Algorithm reports the canonical key under which this scheme registers.
	Algorithm() Algorithm
	// Writer wraps dst so writes are sealed under key with aad; Close writes
	// the final authenticated chunk.
	Writer(key Key, dst io.Writer, aad []byte) (io.WriteCloser, error)
	// Reader wraps src so reads are opened under key with aad; a truncated
	// stream surfaces as StreamTruncated from the returned reader.
	Reader(key Key, src io.Reader, aad []byte) (io.Reader, error)
}
